package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.convert.FromString;
import org.joda.time.base.BasePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Period_normalizedStandard_TriageGen2Test {

    @Test
    public void testNormalizedStandard_BasicDuration() {
        // Test conversion of days, hours, minutes, seconds, millis to a standard duration
        Period period = new Period(1, 2, 3, 4, 5, 6, 7, 8); // Y, M, W, D, H, m, s, ms
        // Note: The method calculates millis based on: millis, seconds, minutes, hours, days, weeks
        // It ignores years and months in the 'millis' calculation, but re-applies them later.

        Period normalized = period.normalizedStandard(PeriodType.day);

        // The millis calculation: 
        // millis = 8 + (7 * 1000) + (6 * 60000) + (5 * 3600000) + (4 * 86400000) + (1 * 604800000)
        // The result should have the type 'day' (meaning fields are days, hours, mins, etc.)
        assertEquals(PeriodType.day, normalized.getPeriodType());
        assertEquals(4, normalized.getDays());
        assertEquals(5, normalized.getHours());
        assertEquals(6, normalized.getMinutes());
        assertEquals(7, normalized.getSeconds());
        assertEquals(8, normalized.getMillis());
    }

    @Test
    public void testNormalizedStandard_WithYearsAndMonthsOverflow() {
        // Test the branch: if (years != 0 || months != 0)
        // Specifically testing the logic: years = safeAdd(years, months / 12); months = months % 12;
        Period period = new Period(1, 13, 0, 0, 0, 0, 0, 0); // 1 year, 13 months
        Period normalized = period.normalizedStandard(PeriodType.year);

        // 1 year + (13/12) = 2 years. 13 % 12 = 1 month.
        assertEquals(2, normalized.getYears());
        assertEquals(1, normalized.getMonths());
    }

    @Test
    public void testNormalizedStandard_WithYearsAndMonthsNoOverflow() {
        // Test the branch where years/months exist but don't overflow into extra years
        Period period = new Period(0, 6, 0, 0, 0, 0, 0, 0);
        Period normalized = period.normalizedStandard(PeriodType.month);

        assertEquals(0, normalized.getYears());
        assertEquals(6, normalized.getMonths());
    }

    @Test
    public void testNormalizedStandard_ZeroYearsAndMonths() {
        // Test the branch where years and months are both 0
        Period period = new Period(0, 0, 1, 1, 1, 1, 1, 1);
        Period normalized = period.normalizedStandard(PeriodType.day);

        assertEquals(0, normalized.getYears());
        assertEquals(0, normalized.getMonths());
        assertEquals(1, normalized.getWeeks());
        assertEquals(1, normalized.getDays());
    }

    @Test
    public void testNormalizedStandard_NegativeValues() {
        // Test with negative values to ensure long arithmetic remains correct
        Period period = new Period(0, 0, 0, 0, -1, -1, -1, -1);
        Period normalized = period.normalizedStandard(PeriodType.standard);

        assertEquals(-1, normalized.getHours());
        assertEquals(-1, normalized.getMinutes());
        assertEquals(-1, normalized.getSeconds());
        assertEquals(-1, normalized.getMillis());
    }

    @Test
    public void testNormalizedStandard_LargeValues() {
        // Test that long casting prevents overflow during millis calculation
        // Using large values for days and weeks
        Period period = new Period(0, 0, Integer.MAX_VALUE, Integer.MAX_VALUE, 0, 0, 0, 0);
        Period normalized = period.normalizedStandard(PeriodType.day);

        // If overflow occurred, the result would be negative or incorrect.
        // We just check if it's positive and consistent.
        assertTrue(normalized.getDays() > 0);
        assertEquals(Integer.MAX_VALUE, normalized.getWeeks());
    }

    @Test
    public void testNormalizedStandard_YearsOnly() {
        // Test the branch where years != 0 but months == 0
        Period period = new Period(5, 0, 0, 0, 0, 0, 0, 0);
        Period normalized = period.normalizedStandard(PeriodType.year);

        assertEquals(5, normalized.getYears());
        assertEquals(0, normalized.getMonths());
    }

    @Test
    public void testNormalizedStandard_MonthsOnly() {
        // Test the branch where months != 0 but years == 0
        Period period = new Period(0, 5, 0, 0, 0, 0, 0, 0);
        Period normalized = period.normalizedStandard(PeriodType.month);

        assertEquals(0, normalized.getYears());
        assertEquals(5, normalized.getMonths());
    }
}
